# Let's fetch the details for each song_id in all_song_ids using the show_song API.
# We'll build a mapping from song_id to (title, artist) for easy lookup.

song_id_to_details = {}
for song_id in all_song_ids:
    song = apis.spotify.show_song(song_id=song_id)
    # Assume at least one artist per song
    artist_name = song["artists"][0]["name"] if song["artists"] else ""
    song_id_to_details[song_id] = {
        "title": song["title"],
        "artist": artist_name
    }
print(song_id_to_details)

